"use client";

import React, { useState } from "react";
import * as LucideIcons from "lucide-react";
import { Button } from "../../../components/ui/Button";
import { Input } from "../../../components/ui/Input";

// Safe icon renderer
function Icon({ name, className }: { name: string, className?: string }) {
    const LucideIcon = (LucideIcons as any)[name];
    if (!LucideIcon) return <div className={className} style={{ width: '20px', height: '20px', backgroundColor: '#333', borderRadius: '4px' }} />;
    return <LucideIcon className={className} />;
}

export default function AdminMarketing() {
    // Virgin campaigns
    const [campaigns, setCampaigns] = useState<any[]>([]);

    const [isModalOpen, setIsModalOpen] = useState(false);
    const [newCampaign, setNewCampaign] = useState({ name: "", channel: "WhatsApp" });

    const handleAddCampaign = (e: React.FormEvent) => {
        e.preventDefault();
        if (!newCampaign.name) return;

        const camp = {
            id: Date.now(),
            ...newCampaign,
            reached: 0,
            converted: 0,
            status: "ATIVA"
        };

        setCampaigns([camp, ...campaigns]);
        setNewCampaign({ name: "", channel: "WhatsApp" });
        setIsModalOpen(false);
    };

    const stopCampaign = (id: number) => {
        setCampaigns(prev => prev.map(c => c.id === id ? { ...c, status: "CONCLUÍDA" } : c));
    };

    return (
        <div className="min-h-screen bg-[#0a0a0a] text-white p-6 lg:p-12 font-sans selection:bg-[#D4AF37] selection:text-black animate-fade-in-up uppercase">
            <header className="mb-10 lg:mb-12 flex flex-col md:flex-row md:items-center justify-between gap-6">
                <div>
                    <h1 className="text-3xl font-semibold mb-1">
                        Centro de <span className="text-[#D4AF37]">Marketing</span>
                    </h1>
                    <p className="text-gray-400 text-sm tracking-widest lowercase">Fidelize seus clientes com inteligência</p>
                </div>
                <div className="flex gap-4">
                    <Button onClick={() => setIsModalOpen(true)} className="gap-2 h-12 bg-[#D4AF37] text-black font-black tracking-widest rounded-2xl">
                        <Icon name="Plus" className="w-4 h-4" /> Nova Campanha
                    </Button>
                </div>
            </header>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-8 mb-16">
                {[
                    { title: "Alcance Total", value: "0", icon: "Users", sub: "impacto direto" },
                    { title: "Taxa CVR", value: "0%", icon: "Target", sub: "agendamentos" },
                    { title: "ROI Estimado", value: "0x", icon: "TrendingUp", sub: "retorno lucro" },
                ].map((stat, i) => (
                    <div key={i} className="bg-[#111111] border border-[#1f1f1f] p-8 rounded-[32px] relative overflow-hidden group">
                        <div className="absolute top-0 right-0 w-32 h-32 bg-[#D4AF37]/5 rounded-bl-full group-hover:bg-[#D4AF37]/10 transition-all pointer-events-none" />
                        <Icon name={stat.icon} className="w-8 h-8 text-[#D4AF37] mb-6" />
                        <p className="text-gray-600 text-[9px] font-black tracking-[0.3em] mb-1">{stat.title}</p>
                        <h3 className="text-3xl font-black mb-2 tracking-tight">{stat.value}</h3>
                        <p className="text-[9px] text-gray-400 tracking-tighter lowercase">{stat.sub}</p>
                    </div>
                ))}
            </div>

            <div className="space-y-6">
                <h3 className="text-lg font-black tracking-[0.2em] text-[#D4AF37] mb-8">Campanhas em Execução</h3>
                <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
                    {campaigns.length > 0 ? campaigns.map((camp) => (
                        <div key={camp.id} className={`bg-[#111111] border p-8 rounded-[40px] flex items-center justify-between group transition-all duration-500 ${camp.status === 'ATIVA' ? 'border-[#1f1f1f] hover:border-[#D4AF37]/30' : 'border-transparent opacity-50 grayscale'}`}>
                            <div className="flex items-center gap-8">
                                <div className={`w-16 h-16 rounded-3xl flex items-center justify-center border transition-all ${camp.status === 'ATIVA' ? 'bg-[#D4AF37]/5 border-[#D4AF37]/20 text-[#D4AF37]' : 'bg-[#1a1a1a] border-[#222] text-gray-500'}`}>
                                    <Icon name={camp.channel === 'WhatsApp' ? 'MessageCircle' : camp.channel === 'SMS' ? 'Smartphone' : 'Instagram'} className="w-8 h-8" />
                                </div>
                                <div>
                                    <h4 className="font-black text-xl mb-1 tracking-tighter italic">{camp.name}</h4>
                                    <div className="flex gap-6 text-[9px] font-black text-gray-500 tracking-widest">
                                        <span className="flex items-center gap-1"><Icon name="Eye" className="w-3 h-3" /> {camp.reached} Alcance</span>
                                        <span className="text-emerald-500 flex items-center gap-1"><Icon name="Zap" className="w-3 h-3" /> {camp.converted} Cliques</span>
                                    </div>
                                </div>
                            </div>
                            <div className="text-right">
                                {camp.status === 'ATIVA' ? (
                                    <button onClick={() => stopCampaign(camp.id)} className="text-[9px] font-black bg-red-500/10 text-red-500 border border-red-500/20 px-4 py-2 rounded-full hover:bg-red-500 hover:text-white transition-all uppercase tracking-widest">Parar</button>
                                ) : (
                                    <span className="text-[9px] font-black text-gray-600 tracking-widest">Finalizada</span>
                                )}
                            </div>
                        </div>
                    )) : (
                        <p className="text-center text-gray-600 italic py-10 col-span-full">Nenhuma campanha cadastrada.</p>
                    )}
                </div>
            </div>

            {isModalOpen && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
                    <div className="absolute inset-0 bg-black/95 backdrop-blur-xl" onClick={() => setIsModalOpen(false)} />
                    <div className="relative w-full max-w-lg bg-[#111111] border border-[#1f1f1f] rounded-[48px] p-12 shadow-2xl animate-fade-in-up">
                        <header className="flex justify-between items-center mb-10">
                            <h2 className="text-3xl font-black italic tracking-tighter">Lançar Campanha</h2>
                            <button onClick={() => setIsModalOpen(false)}><Icon name="X" className="w-8 h-8 text-gray-500" /></button>
                        </header>
                        <form onSubmit={handleAddCampaign} className="space-y-8">
                            <div className="space-y-2">
                                <label className="text-[10px] font-black text-gray-500 tracking-[0.2em] ml-2">Título da Promoção</label>
                                <Input
                                    value={newCampaign.name}
                                    onChange={e => setNewCampaign({ ...newCampaign, name: e.target.value })}
                                    className="bg-[#1a1a1a] border-transparent h-16 rounded-3xl"
                                    placeholder="Ex: Combo Barba + Cabelo"
                                />
                            </div>
                            <div className="space-y-4">
                                <p className="text-[10px] font-black text-gray-500 tracking-[0.2em] ml-2">Canal de Disparo</p>
                                <div className="grid grid-cols-2 gap-4">
                                    {["WhatsApp", "Instagram", "SMS", "E-mail"].map(channel => (
                                        <button
                                            key={channel}
                                            type="button"
                                            onClick={() => setNewCampaign({ ...newCampaign, channel })}
                                            className={`h-14 rounded-2xl border transition-all text-[10px] font-bold tracking-widest ${newCampaign.channel === channel ? 'bg-[#D4AF37] border-transparent text-black' : 'bg-[#1a1a1a] border-transparent text-gray-600 hover:border-gray-800'}`}
                                        >
                                            {channel}
                                        </button>
                                    ))}
                                </div>
                            </div>
                            <Button type="submit" className="w-full h-16 bg-white text-black font-black tracking-[0.3em] rounded-3xl mt-4 hover:bg-[#D4AF37] transition-all">Ativar Agora</Button>
                        </form>
                    </div>
                </div>
            )}
        </div>
    );
}
